# Describes the content type that a client supports in various
# result literals like `Hover`, `ParameterInfo` or `CompletionItem`.

# Please note that `MarkupKinds` must not start with a `$`. These kinds
# are reserved for internal usage.

class MarkupKind(Enum):

    # Plain text is supported as a content format.
    PlainText = "plaintext"

    # Markdown is supported as a content format.
    Markdown = "markdown"

# commented out, because there is already an enumeration with the same name
# MarkupKind = Literal["plaintext", "markdown"]


# A `MarkupContent` literal represents a string value whose content is
# interpreted based on its kind flag. Currently, the protocol supports
# `plaintext` and `markdown` as markup kinds.

# If the kind is `markdown` then the value can contain fenced code blocks like
# in GitHub issues.

# Here is an example how such a string can be constructed using
# JavaScript / TypeScript:
# ```typescript
# let markdown: MarkdownContent = {
# kind: MarkupKind.Markdown,
# value: [
# ʼ# Headerʼ,
# ʼSome textʼ,
# ʼ```typescriptʼ,
# ʼsomeCode();ʼ,
# ʼ```ʼ
# ].join(ʼ\nʼ)
# };
# ```

# *Please Note* that clients might sanitize the returned markdown. A client
# could decide to remove HTML from the markdown to avoid script execution.


class MarkupContent(TypedDict):

    # The type of the Markup.
    kind: MarkupKind

    # The content itself.
    value: str


# Client capabilities specific to the used markdown parser.

# @since 3.16.0


class MarkdownClientCapabilities(TypedDict):

    # The name of the parser.
    parser: str

    # The version of the parser.
    version: NotRequired[str]

    # A list of HTML tags that the client allows / supports in
    # Markdown.

    # @since 3.17.0
    allowedTags: NotRequired[List[str]]


