ChangeAnnotationsSupportOptions = 'ChangeAnnotationsSupportOptions_0'


# The kind of resource operations supported by the client.

ResourceOperationKind = Literal["create", "rename", "delete"]

class ResourceOperationKind(Enum):

    # Supports creating new files and folders.
    Create = "create"

    # Supports renaming existing files and folders.
    Rename = "rename"

    # Supports deleting existing files and folders.
    Delete = "delete"

FailureHandlingKind = Literal["abort", "transactional", "undo", "textOnlyTransactional"]

class FailureHandlingKind(Enum):

    # Applying the workspace change is simply aborted if one of the changes
    # provided fails. All operations executed before the failing operation
    # stay executed.
    Abort = "abort"

    # All operations are executed transactionally. That means they either all
    # succeed or no changes at all are applied to the workspace.
    Transactional = "transactional"

    # If the workspace edit contains only textual file changes they are
    # executed transactionally. If resource changes (create, rename or delete
    # file) are part of the change the failure handling strategy is abort.
    TextOnlyTransactional = "textOnlyTransactional"

    # The client tries to undo the operations already executed. But there is no
    # guarantee that this is succeeding.
    Undo = "undo"


