# commented out, because there is already an enumeration with the same name
# CompletionItemTag = Literal[1]


# A special text edit to provide an insert and a replace operation.

# @since 3.16.0


class InsertReplaceEdit(TypedDict):

    # The string to be inserted.
    newText: str

    # The range if the insert is requested.
    insert: Range

    # The range if the replace is requested.
    replace: Range


# How whitespace and indentation is handled during completion
# item insertion.

# @since 3.16.0

class InsertTextMode(IntEnum):

    # The insertion or replace strings are taken as-is. If the
    # value is multiline, the lines below the cursor will be
    # inserted using the indentation defined in the string value.
    # The client will not apply any kind of adjustments to the
    # string.
    asIs = 1

    # The editor adjusts leading whitespace of new lines so that
    # they match the indentation up to the cursor of the line for
    # which the item is accepted.

    # Consider a line like this: <2tabs><cursor><3tabs>foo. Accepting a
    # multi line completion item is indented using 2 tabs and all
    # following lines inserted will be indented using 2 tabs as well.
    adjustIndentation = 2

# commented out, because there is already an enumeration with the same name
# InsertTextMode = Literal[1, 2]


