# The kind of a code action.

# Kinds are a hierarchical list of identifiers separated by `.`,
# e.g. `"refactor.extract.function"`.

# The set of kinds is open and the client needs to announce
# the kinds it supports to the server during initialization.

CodeActionKind = str


# A set of predefined code action kinds.

class CodeActionKind(Enum):

    # Empty kind.
    Empty = ""

    # Base kind for quickfix actions: ʼquickfixʼ.
    QuickFix = "quickfix"

    # Base kind for refactoring actions: ʼrefactorʼ.
    Refactor = "refactor"

    # Base kind for refactoring extraction actions: ʼrefactor.extractʼ.

    # Example extract actions:

    # - Extract method
    # - Extract function
    # - Extract variable
    # - Extract interface from class
    # - ...
    RefactorExtract = "refactor.extract"

    # Base kind for refactoring inline actions: ʼrefactor.inlineʼ.

    # Example inline actions:

    # - Inline function
    # - Inline variable
    # - Inline constant
    # - ...
    RefactorInline = "refactor.inline"

    # Base kind for refactoring move actions: ʼrefactor.moveʼ

    # Example move actions:

    # - Move a function to a new file
    # - Move a property between classes
    # - Move method to base class
    # - ...

    # @since 3.18.0
    RefactorMove = "refactor.move"

    # Base kind for refactoring rewrite actions: ʼrefactor.rewriteʼ.

    # Example rewrite actions:

    # - Convert JavaScript function to class
    # - Add or remove parameter
    # - Encapsulate field
    # - Make method static
    # - ...
    RefactorRewrite = "refactor.rewrite"

    # Base kind for source actions: `source`.

    # Source code actions apply to the entire file.
    Source = "source"

    # Base kind for an organize imports source action:
    # `source.organizeImports`.
    SourceOrganizeImports = "source.organizeImports"

    # Base kind for a ʼfix allʼ source action: `source.fixAll`.

    # ʼFix allʼ actions automatically fix errors that have a clear fix that
    # do not require user input. They should not suppress errors or perform
    # unsafe fixes such as generating new types or classes.

    # @since 3.17.0
    SourceFixAll = "source.fixAll"

    # Base kind for all code actions applying to the entire notebookʼs scope. CodeActionKinds using
    # this should always begin with `notebook.`

    # @since 3.18.0
    Notebook = "notebook"


